func TestTurnEndBudgetWithin(t *testing.T) {
	t.Parallel()

	tests := []struct {
		hookTimeout time.Duration
		want        time.Duration
	}{
		{hookTimeout: 0, want: 0},
		{hookTimeout: time.Second, want: 0},
